SELECT id, session_id, event_time, duration_sec, page, ROUND(AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS duration_sec_moving_avg_3, COUNT(*) OVER (PARTITION BY page) AS page_count FROM web_events ORDER BY duration_sec DESC;
